document.addEventListener('click', (event) => {
  const tintBtn = event.target.closest('[data-appearance-tint]');
  if (tintBtn) {
    event.preventDefault();
    setAppearanceTint(tintBtn.getAttribute('data-appearance-tint'));
    return;
  }

  const fontBtn = event.target.closest('[data-appearance-font]');
  if (fontBtn) {
    event.preventDefault();
    setAppearanceFont(fontBtn.getAttribute('data-appearance-font'));
    return;
  }

  const dismissTarget = event.target.closest('[data-pf-dismiss-action]');
  if (dismissTarget && event.target === dismissTarget) {
    const fn = window[dismissTarget.getAttribute('data-pf-dismiss-action')];
    if (typeof fn === 'function') fn();
    return;
  }

  const actionEl = event.target.closest('[data-pf-action]');
  if (actionEl) {
    const action = actionEl.getAttribute('data-pf-action');
    if (PF_DELEGATED_ACTIONS.has(action) && typeof window[action] === 'function') {
      event.preventDefault();
      window[action](event, actionEl);
      return;
    }
  }

  const tradingEl = event.target.closest('[data-pf-trading-page]');
  if (tradingEl) {
    event.preventDefault();
    const page = tradingEl.getAttribute('data-pf-trading-page');
    showPage(page, document.getElementById('nav-trading'), { scrollToTop: true });
    const after = tradingEl.getAttribute('data-pf-after-nav');
    if (after && typeof window[after] === 'function') window[after]();
    return;
  }

  // An Arsenal desk card. It carries its OWN attribute rather than reusing
  // data-pf-trading-page: the Trading hero's section tabs are addressed by
  // that attribute, and four more elements answering to it on the dashboard
  // meant a click meant for the section tab could land on a card instead —
  // which navigated to the right page but the wrong TAB, leaving the Fib
  // Boundary panel hidden and its Backtest button unclickable.
  const deskEl = event.target.closest('[data-pf-desk-page]');
  if (deskEl) {
    event.preventDefault();
    showPage(deskEl.getAttribute('data-pf-desk-page'), document.getElementById('nav-trading'), { scrollToTop: true });
    const deskAfter = deskEl.getAttribute('data-pf-after-nav');
    if (deskAfter && typeof window[deskAfter] === 'function') window[deskAfter]();
    // Deep-link to the strategy's own tab, so a card opens the strategy it
    // advertises rather than whichever tab happened to be open last.
    const deskTab = deskEl.getAttribute('data-pf-desk-tab');
    if (deskTab && typeof showOptionsCascadeTab === 'function') {
      showOptionsCascadeTab(null, { getAttribute: (name) => (name === 'data-oc-tab' ? deskTab : null) });
    }
    return;
  }

  const architectureEl = event.target.closest('[data-pf-architecture-view]');
  if (architectureEl) {
    event.preventDefault();
    openArchitectureView(architectureEl.getAttribute('data-pf-architecture-view'));
    return;
  }

  const navEl = event.target.closest('[data-pf-nav-page]');
  if (navEl) {
    event.preventDefault();
    const page = navEl.id === 'nav-trading'
      ? _storedView(
          PF_VIEW_STATE.tradingPage,
          Object.keys(TRADING_SECTION_BY_PAGE),
          'options-cascade-page'
        )
      : navEl.getAttribute('data-pf-nav-page');
    const btnId = navEl.getAttribute('data-pf-nav-tab');
    showPage(page, btnId ? document.getElementById(btnId) : navEl);
    const after = page === 'options-cascade-page'
      ? 'initOptionsCascadePage'
      : page === 'scalp-page'
        ? 'initScalpPage'
        : page === 'stock-terminal-page'
          ? 'initStockTerminalPage'
          : navEl.getAttribute('data-pf-after-nav');
    if (after && typeof window[after] === 'function') window[after]();
  }
});

async function applyNavState(state) {
  const page = (state && state.page && document.getElementById(state.page)) ? state.page : 'dashboard-page';
  const btn = document.getElementById(NAV_BUTTON_MAP[page] || '');
  showPage(page, btn, { pushHistory: false, historyState: state });
  if (page === 'live-page') startLiveMonitor();
  if (page === 'stock-terminal-page') initStockTerminalPage();
  if (page === 'insights-page') initInsightsPage();
  if (page === 'scalp-page') initScalpPage();
  if (page === 'options-cascade-page') initOptionsCascadePage();
  if (page === 'charts-page') initChartsPage();
  if (page === 'results-page' && Number.isFinite(Number(state?.runId)) && Number(state.runId) > 0 && currentViewingRunId !== Number(state.runId)) {
    await viewRun(Number(state.runId), { pushHistory: false });
  }
  if (page === 'assets-page') initArchitecturePage(state?.architectureView || null);
  // Leaving the blueprint by any other route must give the header back: the
  // frozen top belongs to that one page, and nothing else re-runs the init.
  else _setBlueprintFrozenHeader(false);
}

