async function armFibBoundaryLive(_event, button) {
  const symbol = _fibxSymbolFor(button);
  if (!symbol) { _fibSetFormStatus('No ladder to arm.', 'error'); return; }
  // Real money. The confirm is this site's own dialog, and the route behind it
  // demands a password and an authenticator code on top. It names the ONE
  // instrument being opened -- arming is per ladder, never the whole board.
  const ok = await customConfirm(
    `From the next decision on, the <strong>${escapeHtml(symbol)}</strong> ladder places <strong>REAL F&amp;O orders</strong> on Dhan. `
    + 'Rungs it already refused stay refused, and no other ladder is armed by this. '
    + 'You will be asked for your password and authenticator code.',
    { title: `Arm ${symbol} live execution?`, okText: 'Arm live', cancelText: 'Stay unarmed' },
  );
  if (!ok) return;
  try {
    const response = await fetch(`/api/fib-boundary/live/${encodeURIComponent(symbol)}/arm`, { method: 'POST', credentials: 'same-origin' });
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(_apiErrorMessage(data, `Could not arm (${response.status})`));
    _fibSetFormStatus(`${symbol} LIVE ARMED — its orders from here on reach the exchange.`, 'success');
  } catch (error) {
    _fibSetFormStatus(error.message || 'Could not arm live execution.', 'error');
  }
  await refreshFibBoundaryStatus();
}

let _fibxChartCtx = null;
let _fibxChartTf = '';
// Which chart _fibxChartTf belongs to; a new one starts on its own mother's tf.
let _fibxChartKey = '';
let _fibxChartDrawnKey = '';

function openFibAutoChart(_event, button) {
  const symbol = button?.dataset?.symbol || document.getElementById('oc-fib-symbol')?.value || 'NIFTY';
  const setting = (_lastFibBoundaryAuto || {})[symbol] || {};
  const today = new Date().toLocaleDateString('en-CA', { timeZone: 'Asia/Kolkata' });
  // The mother it is on, the one it is waiting for, else today's 09:15.
  const stamp = String(setting.last_mother || setting.waiting_for || `${today}T09:15:00`).slice(0, 19);
  _fibxChartCtx = { symbol, side: 'CE', timestamp: stamp, baseTf: '5m', isCampaign: false };
  loadFibBoundaryChart();
}

async function loadFibBoundaryChart(_event, button) {
  const el = id => document.getElementById(id);
  // The clicked panel's own campaign owns the question; the idle panel has no
  // symbol, so the form answers instead and the chart can be read before Start.
  const ctx = (!_event && !button && _fibxChartCtx) ? _fibxChartCtx : null;
  const campaign = ctx ? null : _lastFibBoundaryStatus?.[_fibxSymbolFor(button)];
  const timestamp = ctx?.timestamp || campaign?.mother_timestamp || el('oc-fib-mother-timestamp')?.value;
  const symbol = ctx?.symbol || campaign?.symbol || el('oc-fib-symbol')?.value || 'NIFTY';
  const side = ctx?.side || campaign?.side || el('oc-fib-side')?.value || 'CE';
  const baseTf = ctx?.baseTf || campaign?.timeframe || _fibTimeframe();
  // EVERYTHING THE ARCHIVED ROW HANDED OVER, kept. This used to rebuild the
  // context from the four fields it had just read and drop `closedAt` and
  // `campaignId` on the floor -- which the strip's Refresh and its 1M/5M/15M/1H
  // buttons then re-entered with. So the FIRST draw of a closed campaign was
  // right and every redraw after it ran to today and lost its buy and sell
  // marks, which is what made the bug look like it came and went.
  _fibxChartCtx = {
    symbol, side, timestamp, baseTf,
    isCampaign: ctx ? ctx.isCampaign : !!campaign,
    closedAt: ctx?.closedAt || '',
    campaignId: ctx?.campaignId || '',
    buyMode: ctx?.buyMode || '',
  };
  // A different campaign is a different chart: the view timeframe must not be
  // inherited from the last one it was left on. Its own mother's timeframe is
  // the only sane default.
  if (_fibxChartKey !== `${symbol}|${side}|${timestamp}`) { _fibxChartTf = ''; _fibxChartKey = `${symbol}|${side}|${timestamp}`; }
  const timeframe = _fibxChartTf || baseTf;
  const chart = el('oc-fib-chart');
  const meta = el('oc-fib-chart-meta');
  const overlay = el('oc-fib-chart-overlay');
  const title = el('oc-fib-chart-title');
  if (!timestamp) { _fibSetFormStatus('Pick a mother timestamp first.', 'error'); return; }
  pfSetCascadeChartOverlayOpen(overlay, true);
  // A closed campaign says so IN THE LOADER. openArchivedFibChart used to
  // stamp "Closed campaign · frozen" after its await, so the loader's own live
  // title won every redraw -- press Refresh on a finished trade and it read as
  // a running one.
  const frozen = !!_fibxChartCtx?.closedAt;
  if (title) title.textContent = (frozen ? 'Closed campaign · frozen · ' : '')
    + `${symbol} ${side} fib ladder · ${String(baseTf).toUpperCase()} mother · ${String(timeframe).toUpperCase()} chart`;
  // The site strip: timeframes + refresh, once. Zoom lives on the canvas host.
  const stripHost = el('oc-fib-chart-strip');
  // REBUILT WHEN THE CHART CHANGES, not once per page. Guarding on
  // childElementCount alone left the first campaign's timeframe highlighted for
  // every campaign opened after it -- the same trap the High Entry strip had.
  // The key is the chart plus its active tf, so redrawing the same chart at the
  // same timeframe still leaves the strip alone.
  const stripKey = `${symbol}|${side}|${timestamp}|${timeframe}`;
  if (stripHost && (!stripHost.childElementCount || stripHost.dataset.stripKey !== stripKey) && typeof pfChartStrip === 'function') {
    stripHost.dataset.stripKey = stripKey;
    stripHost.replaceChildren();
    pfChartStrip(stripHost, {
      timeframes: ['1m', '5m', '15m', '1h'],
      active: timeframe,
      onTimeframe: (tf) => { _fibxChartTf = tf; loadFibBoundaryChart(); },
      onRefresh: () => loadFibBoundaryChart(),
      // No onClose here: this dialog has its own ✕ in the markup, which is
      // there even when the chart fails and the strip is never drawn. Passing
      // one made the strip inject a second (Phil, 2026-08-27: "Why two X").
    });
  }
  // No "Loading…" flash over a chart that is already showing — the old frame
  // holds until the new data arrives, then one clean repaint (the flicker
  // Phil reported, 2026-08-13).
  if (chart && !chart.querySelector('#pf-bench-canvas-host')) {
    chart.innerHTML = `<div class="pf-cascade-chart-empty">Loading closed ${escapeHtml(symbol)} ${escapeHtml(timeframe)} candles…</div>`;
  }
  try {
    // base_timeframe is the MOTHER's timeframe and decides every price on this
    // chart; timeframe only picks the candles drawn underneath them. Sending
    // one parameter for both meant the 1M/5M/15M/1H buttons rebuilt the ladder
    // -- a different swing, different level prices, no longer the ones the
    // engine was working, with nothing on screen saying so.
    // The chart has to be drawn for the mode being traded: under "where two
    // meet" the full level ladder is not what the campaign can buy.
    const mode = campaign?.buy_mode || _fibxChartCtx?.buyMode || _fibBuyMode();
    _fibxChartCtx.buyMode = mode;
    const query = new URLSearchParams({ mother_timestamp: timestamp, symbol, side, timeframe, base_timeframe: baseTf, buy_mode: mode });
    // Only a finished campaign carries one; a live panel wants today's edge.
    const closedAt = ctx?.closedAt || campaign?.closed_at || '';
    if (closedAt) query.set('closed_at', String(closedAt));
    // Which stored campaign's buys and sells to draw. Without it the chart
    // borrows the RUNNING campaign's fills, which belong to a different trade.
    if (ctx?.campaignId) query.set('campaign_id', String(ctx.campaignId));
    const response = await fetch(`/api/fib-boundary/paper/chart?${query.toString()}`, { credentials: 'same-origin', cache: 'no-store' });
    const data = await response.json().catch(() => ({}));
    if (!response.ok || data.status !== 'ok') throw new Error(_apiErrorMessage(data, `Chart failed (${response.status})`));
    // Only one canvas chart can be mounted at a time -- the renderer finds its
    // surfaces by a fixed id. Fold the backtest journal chart away first so the
    // overlay does not mount behind a duplicate host.
    _fibBoundaryCollapseBacktestChart();
    // A CLOSED CAMPAIGN OVERRIDES THE RUNNING ONE. Without this the payload
    // builder resolves `campaign` to _lastFibBoundaryStatus[symbol] and draws
    // today's target, average entry, buy stop, rung states and rupees over an
    // archived trade -- and trims its bars to today's window, which empties and
    // silently falls back to every bar. The route now sends the ladder as it
    // stood; it wins whenever there is one.
    const benchPayload = _fibBoundaryCanvasPayload(data, _fibxChartCtx?.isCampaign ? symbol : '', data.campaign || null);
    // An already-mounted canvas is UPDATED in place, never torn down and
    // rebuilt: replacing the canvas element is the flicker (the compositor
    // shows the fresh blank element before its first paint commits, which is
    // exactly what Phil kept seeing on timeframe clicks). The viewport
    // survives a same-timeframe refresh; a new timeframe refits.
    const mountedHost = chart ? chart.querySelector('#pf-bench-canvas-host') : null;
    const canvasIsThisChart = mountedHost && typeof _pfChartCanvas !== 'undefined' && _pfChartCanvas?.host === mountedHost;
    const drawnKey = `${symbol}|${side}|${timestamp}|${data.timeframe || timeframe}`;
    const view = canvasIsThisChart && drawnKey === _fibxChartDrawnKey && typeof _pfChartCanvasRefreshState === 'function' ? _pfChartCanvasRefreshState() : null;
    const refreshed = canvasIsThisChart && typeof _pfChartCanvasRefresh === 'function' && _pfChartCanvasRefresh(benchPayload, view);
    if (!refreshed && chart && typeof pfBenchDrawChart === 'function') {
      // A FIRST mount sizes itself off the measured host, so it must not draw
      // in the frame the overlay opened — that yields a 2px canvas. The
      // in-place refresh above is already sized and needs no wait.
      await pfWaitForCascadeChartLayout();
      pfBenchDrawChart(chart, benchPayload);
    }
    _fibxChartDrawnKey = drawnKey;
    if (meta) {
      // When the view is finer than the mother, say which timeframe the prices
      // came from. "closed 5M candles · swing 24427.95-24677.05" otherwise
      // reads as a 5M swing, and it is not — it is the 1H one, drawn over 5M
      // candles so you can see inside the bars.
      const readOn = String(data.base_timeframe || data.timeframe).toUpperCase();
      const viewedOn = String(data.timeframe).toUpperCase();
      const source = readOn === viewedOn ? '' : ` · structures read on ${readOn}, not ${viewedOn}`;
      // Fibs STACK, so the caption counts them rather than naming one swing.
      // "swing 24427.95–24677.05" was true of the newest fib and read as though
      // it were the whole ladder, which since the merge it never is.
      const fibs = (data.fibs || []).length;
      const newest = fibs ? data.fibs[fibs - 1] : null;
      const noZones = String(data.buy_mode) === 'convergence' && !(data.zones || []).length;
      meta.textContent = noZones
        ? `${data.candles.length} closed ${viewedOn} candles · ${fibs} fib${fibs === 1 ? '' : 's'} · PARTNER has no zone here — nothing is buyable on this mother yet`
        : newest
        ? `${data.candles.length} closed ${viewedOn} candles · ${fibs} fib${fibs === 1 ? '' : 's'}, ${(data.trendlines || []).length} trendline${(data.trendlines || []).length === 1 ? '' : 's'} · newest ${newest.fib1}–${newest.fib0} (${newest.span} pts) · ${(data.levels || []).length} levels${source} · drag to pan, wheel to zoom, double-click to reset`
        : `${data.candles.length} closed ${viewedOn} candles · ${data.note}`;
    }
  } catch (error) {
    if (typeof _pfChartCanvasTeardown === 'function') _pfChartCanvasTeardown();
    if (chart) chart.innerHTML = `<div class="pf-cascade-chart-empty">${escapeHtml(error.message || 'Unable to load chart.')}</div>`;
    if (meta) meta.textContent = 'Chart unavailable';
  }
}

// Shared by the overlay and the journal toggle: both draw with the one Canvas
// renderer, so opening either has to put the other away.
function _fibBoundaryCollapseBacktestChart() {
  const box = document.getElementById('oc-fib-backtest-chart');
  const btn = document.getElementById('oc-fib-backtest-chart-btn');
  if (box) { box.style.display = 'none'; box.innerHTML = ''; }
  if (btn) btn.textContent = '↗ Journal chart';
}

function hideFibBoundaryChart() {
  const overlay = document.getElementById('oc-fib-chart-overlay');
  pfSetCascadeChartOverlayOpen(overlay, false);
  // The next campaign opens on its own mother chart, not this one's override.
  _fibxChartTf = '';
  _fibxChartDrawnKey = '';
  _fibxChartCtx = null;
  const strip = document.getElementById('oc-fib-chart-strip');
  if (strip) strip.innerHTML = '';
  // A hidden host still holds pointer bindings, a ResizeObserver and a theme
  // MutationObserver. Closing the dialog has to release them.
  if (typeof _pfChartCanvasTeardown === 'function') _pfChartCanvasTeardown();
  const chart = document.getElementById('oc-fib-chart');
  if (chart) chart.innerHTML = '';
}

async function runFibBoundaryBacktest() {
  const el = id => document.getElementById(id);
  // Field for field the same as Start. The two engines are one now, so the
  // two payloads have to be too -- a route test pins that.
  const payload = {
    symbol: el('oc-fib-symbol')?.value || 'NIFTY',
    mother_timestamp: el('oc-fib-mother-timestamp')?.value,
    side: el('oc-fib-side')?.value || 'CE',
    timeframe: _fibTimeframe(),
    buy_mode: _fibBuyMode(),
    intraday_close: _fibIntradayClose(),
    deep_carry: _fibDeepCarry(),
    trailing_target: _fibTrailingTarget(),
    lot_ramp: _fibLotRamp(),
    capital_cap_inr: Number(el('oc-fib-capital-cap')?.value),
    itm_steps: Number(el('oc-fib-itm')?.value),
  };
  if (!payload.mother_timestamp) { _fibSetFormStatus('Pick a mother timestamp to backtest.', 'error'); return; }
  const button = el('oc-fib-backtest-btn');
  if (button) { button.disabled = true; button.textContent = 'Replaying…'; }
  _fibSetFormStatus(`Replaying ${payload.symbol} ${payload.side} on recorded prices…`, 'busy');
  try {
    const response = await fetch('/api/fib-boundary/backtest', { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
    const data = await response.json().catch(() => ({}));
    if (!response.ok || data.status !== 'ok') throw new Error(_apiErrorMessage(data, `Backtest failed (${response.status})`));
    _renderFibBoundaryBacktest(data);
    const net = data.campaign?.net_pnl;
    _fibSetFormStatus(
      net == null ? 'Replayed — no completed round to price.' : `Replayed · net ${_cascadeOptionsMoney(net)}`,
      net == null ? 'muted' : (net >= 0 ? 'success' : 'error'),
    );
  } catch (error) {
    _fibSetFormStatus(error.message || 'Backtest failed.', 'error');
  } finally {
    if (button) { button.disabled = false; button.textContent = '◱ Backtest · real P&L'; }
  }
}

// A replay costs a Dhan round trip per contract and several seconds, and it
// used to survive only as long as the page went undisturbed: the result lived
// in one variable over a panel that starts hidden, so any redraw lost it and
// the only way back was to pay for the whole thing again. The run is filed
// server-side now, so re-opening the page brings the last one back.
//
// Deliberately not awaited by the caller and never fatal: a missing or broken
// saved run must not stop the page from loading.
async function _restoreLastFibBoundaryBacktest() {
  if (_lastFibBacktest) return;  // this session already has one on screen
  try {
    const response = await fetch('/api/fib-boundary/backtests/latest', { credentials: 'same-origin' });
    if (!response.ok) return;
    const data = await response.json().catch(() => ({}));
    const payload = data && data.run && data.run.payload;
    if (!payload || payload.status !== 'ok' || _lastFibBacktest) return;
    _renderFibBoundaryBacktest(payload);
    const when = data.run.created_at ? _cascadeOptionsTimestamp(data.run.created_at) : '';
    const note = document.getElementById('oc-fib-backtest-note');
    if (note && when) note.textContent = `${note.textContent} · saved run from ${when}`;
    const badge = document.getElementById('oc-fib-backtest-badge');
    if (badge && !badge.textContent.startsWith('SAVED')) badge.textContent = `SAVED · ${badge.textContent}`;
    const stale = document.getElementById('oc-fib-backtest-stale');
    if (stale) {
      stale.textContent = `Saved replay${when ? ` from ${when}` : ''} — a stored result, not today's. It keeps the rule it ran `
        + 'under, so an old one can show a ladder the page no longer trades. Backtest replaces it; ✕ Delete throws it away.';
      stale.style.display = '';
    }
  } catch (_error) {
    /* No saved run, or it cannot be read — the panel simply stays closed. */
  }
}

// EVERY buy a campaign made, each counted ONCE. A round that pays at its target
// empties `fills` and keeps the legs on the round; an intraday close, a broken
// mother or a kill books the round AND leaves the legs in `fills` as the
// record. Concatenating the two counted those buys twice -- a 3-buy replay
// said "6 buys" and drew six markers (2026-08-18).
// "23 Jul 12:33" -- the buy table's time column. The full IST stamp is on the
// cell's title; the row has ten columns and the long form wrapped every one
// of them onto four lines.
function _fibShortStamp(value) {
  if (!value) return '—';
  const d = new Date(String(value).replace(/(\.\d+)?(Z|[+-]\d\d:\d\d)?$/, ''));
  if (Number.isNaN(d.getTime())) return String(value).slice(0, 16);
  const mon = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][d.getMonth()];
  return `${d.getDate()} ${mon} ${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`;
}

function _fibCampaignFills(campaign) {
  const c = campaign || {};
  const rounds = Array.isArray(c.rounds) ? c.rounds : [];
  const banked = rounds.reduce(
    (acc, round) => acc.concat((Array.isArray(round.fills) ? round.fills : []).map(f => ({ ...f, round: round.round }))),
    [],
  );
  const key = f => `${f.rung_key || ('L' + f.level)}|${f.timestamp}|${f.buy_number}`;
  const seen = new Set(banked.map(key));
  const open = (Array.isArray(c.fills) ? c.fills : []).filter(f => !seen.has(key(f)));
  return banked.concat(open);
}

// The same trap Candle Entry had: a replay is filed server-side so a reload
// brings it back, and it then reads exactly like a fresh result. Phil, on a
// SENSEX run saved 19 Aug still sitting there on 22 Aug: "the next one no
// delete button stale record... Not sure what to do with this".
async function deleteFibBoundaryBacktest() {
  const confirmed = await customConfirm(
    'Throw this saved replay away? Nothing traded is touched \u2014 it is a recorded backtest, and the same mother can always be replayed again.',
    { title: 'Delete this replay', icon: ICO.warn(28), okText: 'Delete', danger: true },
  );
  if (!confirmed) return;
  let removed = 0;
  try {
    const response = await fetch('/api/fib-boundary/backtests/latest', { method: 'DELETE', credentials: 'same-origin' });
    const data = await response.json().catch(() => ({}));
    if (!response.ok || data.status !== 'ok') throw new Error(_apiErrorMessage(data, 'The replay could not be deleted.'));
    removed = data.removed;
  } catch (error) {
    _fibSetFormStatus(error.message || 'The replay could not be deleted.', 'error');
    return;
  }
  _lastFibBacktest = null;
  _fibBoundaryCollapseBacktestChart();
  const panel = document.getElementById('oc-fib-backtest');
  if (panel) panel.style.display = 'none';
  ['oc-fib-backtest-csv', 'oc-fib-backtest-delete', 'oc-fib-backtest-chart-btn'].forEach(id => {
    const node = document.getElementById(id);
    if (node) node.style.display = 'none';
  });
  const gone = Number(removed) || 0;
  _fibSetFormStatus(
    gone > 1
      ? `${gone} saved replays deleted. Press Backtest to replay a mother fresh.`
      : 'Saved replay deleted. Press Backtest to replay a mother fresh.',
    'success',
  );
}
window.deleteFibBoundaryBacktest = deleteFibBoundaryBacktest;

function _renderFibBoundaryBacktest(data) {
  const panel = document.getElementById('oc-fib-backtest');
  if (panel) panel.style.display = '';
  const c = data.campaign || {};
  // The chart payload is the SAME shape the live chart route returns, so the
  // one translator draws both.
  _lastFibBacktest = { meta: data, chart: data.chart };
  const hasChart = !!(data.chart && Array.isArray(data.chart.candles) && data.chart.candles.length);
  _fibBoundaryCollapseBacktestChart();
  const chartBtn = document.getElementById('oc-fib-backtest-chart-btn');
  if (chartBtn) chartBtn.style.display = hasChart ? '' : 'none';
  const stale = document.getElementById('oc-fib-backtest-stale');
  if (stale) { stale.textContent = ''; stale.style.display = 'none'; }
  const del = document.getElementById('oc-fib-backtest-delete');
  if (del) del.style.display = '';

  const badge = document.getElementById('oc-fib-backtest-badge');
  if (badge) {
    const priced = data.pricing === 'recorded_history';
    const gaps = (c.data_gaps || []).length;
    badge.textContent = !priced ? 'GEOMETRY ONLY' : gaps ? `PRICED · ${gaps} GAP${gaps === 1 ? '' : 'S'}` : 'REAL PREMIUMS';
    badge.style.color = !priced ? 'var(--warn)' : gaps ? '#fde68a' : '#6ee7b7';
    badge.style.borderColor = badge.style.color;
  }
  const contract = document.getElementById('oc-fib-backtest-contract');
  if (contract) {
    contract.textContent = `${data.symbol} ${data.side} · ${String(data.timeframe).toUpperCase()} mother, 1m entries · ${data.lot_size} units/lot`;
  }
  const gist = document.getElementById('oc-fib-backtest-gist');
  if (gist) gist.textContent = data.note || '';

  const summary = document.getElementById('oc-fib-backtest-summary');
  if (summary) {
    const outcome = String(c.exit_reason || c.status || '—').replaceAll('_', ' ');
    summary.innerHTML = [
      _cascadeOptionsMetric('Outcome', outcome.toUpperCase(), c.net_pnl > 0 ? '#6ee7b7' : c.net_pnl < 0 ? '#fca5a5' : 'var(--muted)'),
      _cascadeOptionsMetric('Net P&L', c.net_pnl == null ? '—' : _cascadeOptionsMoney(c.net_pnl), c.net_pnl >= 0 ? '#6ee7b7' : '#fca5a5'),
      _cascadeOptionsMetric('Gross', c.gross_pnl == null ? '—' : _cascadeOptionsMoney(c.gross_pnl)),
      _cascadeOptionsMetric('Costs', c.costs_total == null ? '—' : _cascadeOptionsMoney(c.costs_total), '#fde68a'),
      _cascadeOptionsMetric(
        'Deployed',
        _cascadeOptionsMoney((c.rounds || []).reduce((n, r) => n + (Number(r.deployed_inr) || 0), 0) + (Number(c.deployed_inr) || 0)),
        '#fde68a',
      ),
      _cascadeOptionsMetric('Lots', `${c.open_lots || 0} · ${_fibCampaignFills(c).length} buys`),
    ].join('');
  }

  const note = document.getElementById('oc-fib-backtest-note');
  if (note) {
    const a = c.anchor;
    // A mother that moved on its own has to say so. The engine rebases when
    // price closes past the typed mother before anything is bought, and the
    // chart then measures from a candle the reader never chose.
    const moved = data.chart && data.chart.mother_rebased
      ? ` · mother moved to ${_cascadeOptionsTimestamp(data.chart.mother_timestamp)} (the one typed was passed before any buy)`
      : '';
    const fibCount = (c.fibs || []).length;
    const ended = c.exit_timestamp
      ? ` · ended ${_cascadeOptionsTimestamp(c.exit_timestamp)} (${String(c.exit_reason || c.status || '').replaceAll('_', ' ')})`
      : ` · still open at ${data.horizon_to}`;
    note.textContent = a
      ? `${fibCount} fib${fibCount === 1 ? '' : 's'} drawn · newest ${a.low}–${a.high} (${a.span} pts), confirmed ${_cascadeOptionsTimestamp(a.confirmed_at)}${ended}${moved}`
      : `No fib formed — the swing never settled${ended}.${moved}`;
  }

  const gapsEl = document.getElementById('oc-fib-backtest-gaps');
  if (gapsEl) {
    const gaps = c.data_gaps || [];
    gapsEl.innerHTML = gaps.length
      ? `<div style="padding:8px 10px;border:1px solid rgba(251,191,36,.3);border-radius:7px;color:var(--warn);font:10.5px/1.5 'JetBrains Mono',monospace;"><strong>${gaps.length} pricing gap${gaps.length === 1 ? '' : 's'}</strong><br>${gaps.slice(-5).map(escapeHtml).join('<br>')}</div>`
      : '';
  }

  const legs = document.getElementById('oc-fib-backtest-legs');
  if (legs) {
    // EVERY leg the replay traded, banked rounds included. A round that pays
    // out empties `fills` and parks the mother, so a replay whose OUTCOME says
    // TARGET and whose NET P&L says +Rs 4,941 was showing "No level was
    // touched in this window" underneath it (Phil, 2026-08-16).
    const fills = _fibCampaignFills(c);
    const banked = fills.filter(f => f.round);
    const exits = c.exit_premiums || [];
    legs.innerHTML = fills.length ? fills.map((f, i) => {
      // A banked leg carries what it actually sold for; an open one falls back
      // to the campaign's exit premiums, in the order they were bought.
      const out = f.exit_premium != null ? f.exit_premium : exits[i - banked.length];
      const pnl = out == null ? null : (Number(out) - Number(f.premium)) * Number(f.quantity);
      const color = pnl == null ? 'var(--muted)' : pnl >= 0 ? '#6ee7b7' : '#fca5a5';
      return `<tr style="border-bottom:1px solid var(--border);">`
        + `<td style="padding:7px 8px;"><strong style="color:#38bdf8;">#${escapeHtml(String(f.buy_number))}</strong> ${escapeHtml(String(f.rung_key || ('L' + f.level)))}${f.round ? `<span style="margin-left:5px;font-size:9px;color:var(--muted);">R${escapeHtml(String(f.round))}</span>` : ''}</td>`
        + `<td style="padding:7px 8px;">${escapeHtml(_cascadeOptionsTimestamp(f.timestamp))}</td>`
        + `<td style="padding:7px 8px;text-align:right;">${escapeHtml(_cascadeNumber(f.index_price))}</td>`
        + `<td style="padding:7px 8px;text-align:right;">${escapeHtml(Number(f.strike).toLocaleString('en-IN'))}</td>`
        + `<td style="padding:7px 8px;text-align:right;">₹${escapeHtml(_cascadeNumber(f.premium))}</td>`
        + `<td style="padding:7px 8px;text-align:right;">${escapeHtml(String(f.lots))}</td>`
        + `<td style="padding:7px 8px;text-align:right;">${escapeHtml(String(f.quantity))}</td>`
        + `<td style="padding:7px 8px;text-align:right;">${out == null ? '—' : '₹' + escapeHtml(_cascadeNumber(out))}</td>`
        + `<td style="padding:7px 8px;text-align:right;color:${color};font-weight:800;">${pnl == null ? '—' : escapeHtml(_cascadeOptionsMoney(pnl))}</td>`
        + `</tr>`;
    }).join('') : '<tr><td colspan="9" style="padding:16px;text-align:center;color:var(--muted);">No level was touched in this window.</td></tr>';
  }
}

function toggleFibBoundaryBacktestChart() {
  const box = document.getElementById('oc-fib-backtest-chart');
  const btn = document.getElementById('oc-fib-backtest-chart-btn');
  if (!box) return;
  if (box.style.display !== 'none' && box.innerHTML) {
    box.style.display = 'none';
    box.innerHTML = '';
    if (typeof _pfChartCanvasTeardown === 'function') _pfChartCanvasTeardown();
    if (btn) btn.textContent = '↗ Journal chart';
    return;
  }
  // The same Canvas renderer the Test Bench draws with — bar-index axis, gap
  // blocks, trade markers — instead of the old wall-clock SVG.  Visible
  // first, then drawn: a display:none host measures zero.
  const chart = _lastFibBacktest && _lastFibBacktest.chart;
  if (!chart) return;
  box.style.display = '';
  // Through the SAME translator the live chart uses, with the backtest's own
  // campaign so its fills and level states are the ones drawn.
  if (typeof pfBenchDrawChart === 'function') {
    pfBenchDrawChart(box, _fibBoundaryCanvasPayload(chart, null, _lastFibBacktest.meta?.campaign));
  }
  if (btn) btn.textContent = '× Hide chart';
}


